class Solution {
    public int mostWordsFound(String[] sentences) {
        int maxWords = 0;
        for (String sentence : sentences) {
            maxWords = Math.max(maxWords, sentence.split(" ").length);
        }
        return maxWords;
    }
}

class Solution {
    public int mostWordsFound(String[] sentences) {
        int maxWords = 0;
        for (String sentence : sentences) {
            int words = 1;
            for (int i = 0; i < sentence.length(); i++) {
                if (sentence.charAt(i) == ' ') {
                    words++;
                }
            }
            maxWords = Math.max(maxWords, words);
        }
        return maxWords;
    }
}

class Solution {
    public int mostWordsFound(String[] sentences) {
        int maxWords = 0;
        for (String sentence : sentences) {
            int words = 1;
            int start = 0;
            int next = sentence.indexOf(' ', start);
            while (next != -1) {
                words++;
                start = next + 1;
                next = sentence.indexOf(' ', start);
            }
            maxWords = Math.max(maxWords, words);
        }
        return maxWords;
    }
}

class Solution {
    public int mostWordsFound(String[] sentences) {
        int maxWords = 0;
        for (String sentence : sentences) {
            int spaces = sentence.length() - sentence.replace(" ", "").length();
            maxWords = Math.max(maxWords, spaces + 1);
        }
        return maxWords;
    }
}
